import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    inputs = torch.randn(2, generator=ctx.rng.torch)
    target = int(inputs[0] > 0)
    group_id = int(ctx.index) % 2
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(torch.tensor(target)), "group_ids": synth.Tensor(torch.tensor(group_id))}
dataset = synth.Spec("group-dro-classification", generator=samples, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class Classifier(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=2, out_features=2)
    def forward(self, inputs):
        return {"logits": self.network(inputs)}
trainer = Trainer(Classifier(), train, recipe="structured-objective", recipe_config={"loss": "group-dro", "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "targets"}, "group_ids": {"batch": "group_ids"}}}, batch_size=8, max_epochs=1, device="cpu")
trainer.fit()
